#include "business_store.hpp"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <iostream>
void need(bool b,const char* why){if(!b)throw std::runtime_error(why);}
int main(int argc,char** argv){QCoreApplication a(argc,argv);try{QTemporaryDir tmp;BusinessStore store(tmp.filePath("business.sqlite"));auto topic=store.save("topics",{{"name","设备"}});auto doc=store.save("docs",{{"title","公告"},{"text","测试公司（证券代码600001，上海证券交易所）生产设备。"}});QJsonObject relation{{"topicId",topic["id"]},{"documentId",doc["id"]},{"stage","equipment"},{"claim","生产设备"},{"quote","生产设备"},{"polarity","supports"},{"verification","manuallyVerified"},{"product","设备"},{"company",QJsonObject{{"name","测试公司"},{"instrumentId","SH:stock:600001"},{"identityDocumentId",doc["id"]},{"identityQuote","测试公司（证券代码600001，上海证券交易所）"}}}};auto saved=store.save("relations",relation);auto before=store.read("relations");auto wrong=saved;auto company=wrong["company"].toObject();company["instrumentId"]="SZ:stock:600001";wrong["company"]=company;bool rejected=false;try{store.save("relations",wrong);}catch(...){rejected=true;}need(rejected&&store.read("relations")==before,"identity rejected atomically");auto projection=researchCompanies::project(topic["id"].toString(),store.read("relations"),store.read("docs"),{});need(projection["rows"].toArray().size()==1,"one row");need(projection["rows"].toArray()[0].toObject()["verification"]=="manuallyVerified","manual preserved");need(researchCompanies::project("other",store.read("relations"),store.read("docs"),{})["rows"].toArray().isEmpty(),"topic isolation");
 wrong=doc;wrong["text"]="删去身份依据但保留生产设备";rejected=false;try{store.save("docs",wrong);}catch(...){rejected=true;}need(rejected&&store.read("docs")[0].toObject()["text"]==doc["text"],"linked original protected");
 QJsonObject archived{{"topicId","old"},{"sequence",2},{"relations",QJsonArray{QJsonObject{{"id","r"},{"company",QJsonObject{{"name","旧公司"},{"stockCode","600002"}}},{"product","产品"},{"stage","equipment"},{"status","verified"},{"evidenceRefs",QJsonArray{QJsonObject{{"evidenceId","e"},{"quote","旧引文"}}}}}}}};QJsonObject report{{"id","oldversion"},{"legacySource","industry_research_versions"},{"text",QString::fromUtf8(QJsonDocument(archived).toJson())}};auto rows=researchCompanies::project("legacy-topic:old",{}, {},QJsonArray{report})["rows"].toArray();need(rows.size()==1&&rows[0].toObject()["readOnly"].toBool(),"archived row read-only");need(rows[0].toObject()["status"]=="legacyVerified"&&!rows[0].toObject()["bodyAvailable"].toBool(),"old status not promoted/body unavailable");need(rows[0].toObject()["instrumentId"].toString().isEmpty(),"unbound old code not guessed");std::cout<<"research companies: identity, atomic evidence protection, topics, archived status/source GREEN\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
